#!/bin/bash
cd "$(dirname "$0")/../.."
node scripts/portraits/select-source.js --slug de-anthony-melton --url 'https://images2.minutemediacdn.com/image/upload/c_limit,w_3000,f_jpg,q_92/images/ImagnImages/mmsport/inside_the_warriors/01kbdjt6n146mjc9fa0f.jpg' --page 'https://www.si.com/nba/warriors/onsi/news/predicting-warriors-minutes-distribution-with-melton-seth-curry-in-rotation-01kbdebajdgq' --license 'unknown (Imagn Images on SI.com)' --author 'David Richard / Imagn Images' --date 'c. 2024-11-08 (at CLE, Rocket Mortgage FieldHouse; Cleveland photographer, Donovan Mitchell defending; his only Warriors games before the Dec 2025 upload were Oct-Nov 2024)' --crop 905,311,1250 --scores 3,3,3,2,2,1,1 --energy 6.5 --vs-mccain 'slightly lower (mid-drive, mouth open mid-breath, locked-in look, but eyes ahead-down rather than up and off)' --jersey 'GSW white association #8, 2024-25' --concerns 'SI/Imagn editorial photo, not nba.com, license unknown; game date inferred, not captioned (figcaption only names him and the photographer); 2024-25 rather than 2025-26/2026-27 (same team, same look); Mitchell’s shoulder at the left edge of the crop; nba.com has no usable 2025-26 or 2026 preseason Melton photo (Warriors post no game galleries; nba.com articles reuse two 2024 isos)' --alt 'https://cdn.nba.com/manage/2024/11/melton-iso.jpg (nba.com, GSW blue at POR 2024-25, big frontal face but a full open-mouthed laugh, mood off from McCain)' --alt 'https://images2.minutemediacdn.com/image/upload/c_limit,w_3000,f_jpg,q_92/images/ImagnImages/mmsport/inside_the_warriors/01k6ghhjze44ht8g59vq.jpg (SI, GSW blue, broad smile with hands out, head near profile)' --alt 'https://cdn.nba.com/manage/2024/10/deanthony-melton-iso.jpg (nba.com, GSW blue dribbling, near-neutral, smaller face)'
node scripts/portraits/select-source.js --slug jordan-clarkson --url 'https://images2.minutemediacdn.com/image/upload/c_limit,w_3000,f_jpg,q_92/images/ReutersImages/mmsport/all_knicks/01kxgxc7kqky9wwvd5sh.jpg' --page 'https://www.si.com/nba/knicks/onsi/knicks-set-up-future-jordan-clarkson-trade-bold-move-01kxgxa6thj4' --license 'unknown (Imagn Images via Reuters Connect, on SI.com)' --author 'Imagn Images' --date '2025-26 season (road game, exact game not captioned; image uploaded July 2026)' --crop 1249,40,640 --scores 3,3,3,2,2,2,1 --energy 6 --vs-mccain 'slightly lower (eyes up and off-camera like McCain, lips parted mid-breath, alert; mouth less open)' --jersey 'NYK white association #00, 2025-26' --concerns 'SI/Imagn editorial photo, not nba.com, license unknown; game not captioned (figcaption is generic); white headband covers his hairline; nba.com Knicks articles carry no Getty photo of him and the 2026 preseason Knicks galleries carry a corner logo bug and small faces' --alt 'https://images2.minutemediacdn.com/image/upload/c_limit,w_3000,f_jpg,q_92/images/ReutersImages/mmsport/fantasy_sports_on_si/01kx3xx9vb5hjwckkhk4.jpg (SI fantasy article lead, 2026-03-08 at LAL, blue icon, reacting with mouth in a wide O, energy ~8, head turned 3/4 with braids across the cheek)' --alt 'https://upload.wikimedia.org/wikipedia/commons/6/65/Jordan_Clarkson_NY_Knicks_2025_NBA_Cup.jpg (Commons, Dec 2025 NBA Cup, white, defensive stance, small face, neutral)'
node scripts/portraits/select-source.js --slug jarred-vanderbilt --url 'https://platform.silverscreenandroll.com/wp-content/uploads/sites/144/2025/10/gettyimages-2239589741.jpg?quality=90&strip=all' --page 'https://www.silverscreenandroll.com/lakers-news/96780/jarred-vanderbilt-lakers-suns-warriors-jj-redick-gabe-vincent-preseason-training-camp' --license 'unknown (Getty Images, via Silver Screen and Roll / Vox Media)' --author 'Getty Images' --date 'Oct 2025 (2025-26 preseason at GSW, Chase Center; Getty caption: drives against the Golden State Warriors, NBA preseason game)' --crop 850,22,700 --scores 3,3,3,2,2,2,1 --energy 6.5 --vs-mccain 'slightly lower (frontal, eyes off-camera to his right, mouth open mid-breath with tongue at the teeth, engaged on a drive)' --jersey 'LAL gold icon #2, 2025-26 preseason' --concerns 'not nba.com: Getty photo from an SB Nation article (no watermark), license unknown; 2025-26 preseason game, not regular season; tongue visible between the teeth; white headband covers the hairline; nba.com tags only bench/street-clothes and 2023 photos of him and the Lakers playoff galleries show him nowhere' --alt 'https://images2.minutemediacdn.com/image/upload/c_limit,w_3000,f_jpg,q_92/images/ImagnImages/mmsport/all_lakers/01knfd65bqab8fhnw33a.jpg (SI injury-designation lead, gold, sharp but head near profile, lips barely parted, energy ~5.5)' --alt 'https://cdn.nba.com/manage/2024/12/GettyImages-2149436762.jpg (nba.com, 2024 courtside in street clothes and beanie, off-rule)' --alt 'https://upload.wikimedia.org/wikipedia/commons/9/96/Jarred_Vanderbilt_2026.jpg (Commons, 2026-01-28 at CLE, warmup hoodie, off-rule)'
node scripts/portraits/select-source.js --slug gradey-dick --url 'https://images2.minutemediacdn.com/image/upload/c_limit,w_3000,f_jpg,q_92/images/ImagnImages/mmsport/all_raptors/01kje6x709pe1jrwfj6d.jpg' --page 'https://www.si.com/nba/raptors/onsi/news/toronto-raptors-darko-rajakovic-explains-gradey-dick-struggles' --license 'unknown (Imagn Images on SI.com)' --author 'Trevor Ruszkowski / Imagn Images' --date '2025-26 season, at IND (caption: first half against the Indiana Pacers; image uploaded 2026-02-27)' --crop 700,0,1690 --scores 3,3,2,2,2,2,0 --energy 5.5 --vs-mccain 'slightly lower (sweaty, lips parted mid-breath, focused look-off, but eyes cast down-left and lids heavy; calmer than McCain)' --jersey 'TOR black statement #1, 2025-26' --concerns 'FLAG: Raptors jersey, not his 2026-27 Clippers (traded June 2026; repaint needed); energy at the low edge of the band; SI/Imagn editorial photo, not nba.com, license unknown. The only Clippers in-game photo with a readable face is the alt Getty jumper (McCain-like look, energy 7) but its head is only ~180 px hair-to-chin in a 1500 px web copy; the Oct 10 Vancouver CP photo is neutral and tiny; no Clippers gallery for the Oct 14 DEN game yet' --alt 'https://cdn.nba.com/teams/uploads/sites/1610612746/2026/10/GettyImages-2298058525.jpg (nba.com Clippers gallery, 2026-10-04 preseason vs GSW in Honolulu, LAC white #9, eyes up on a jumper with mouth open, energy 7, but face ~140 px brow-to-chin, too small)' --alt 'https://blogto-production2-baselayer-display.blogto.com/articles/20260703-gradey-dick-toronto-raptors.jpg (blogTO, TOR white, hands on hips looking off, energy ~5, face ~250 px)' --alt 'https://images2.minutemediacdn.com/image/upload/c_limit,w_3000,f_jpg,q_92/images/ImagnImages/mmsport/all_raptors/01kb1gpep6jb559jy09r.jpg (SI, TOR red, standing neutral, mouth closed, energy ~4)'
node scripts/portraits/select-source.js --slug tre-johnson --url 'https://platform.bulletsforever.com/wp-content/uploads/sites/52/2026/03/gettyimages-2265499748.jpg?quality=90&strip=all&crop=25%2C15%2C50%2C75' --page 'https://www.bulletsforever.com/washington-wizards-gamethreads/73413/wizards-at-pelicans-discussion' --license 'unknown (Getty Images, via Bullets Forever / Vox Media)' --author 'Getty Images' --date '2026-03-08 (at NOP, Smoothie King Center; Getty caption: takes a shot over Jeremiah Fears, first half)' --crop 580,543,900 --scores 3,3,3,2,2,2,1 --energy 7 --vs-mccain 'matches (eyes up toward the rim, mouth open mid-breath, engaged; not straining)' --jersey 'WAS red icon #12, 2025-26' --concerns 'not nba.com: Getty photo from an SB Nation page (no watermark), license unknown; URL asks the Vox image server for the centre 3000x3000 of the 6000x4000 original at full resolution, so the face keeps ~440 px instead of being halved by the 3000 px cap; mid-jumper, so his raised arm and the defender’s arm frame the head at both crop edges (face itself clear); white headband over the hairline; 2025-26 rather than 2026-27 (same team); nba.com has no captioned in-game photo of him (Wizards post no game galleries) and Commons has only media-day and college shots' --alt 'https://upload.wikimedia.org/wikipedia/commons/b/bd/Tre_Johnson_Media_Day.jpg (Commons, 2025 media day, posed, off-rule)'
node scripts/portraits/select-source.js --slug kingston-flemings --url 'https://cdn.nba.com/manage/2026/10/GettyImages-2298668755_cropped.jpg' --page 'https://www.nba.com/watch/video/kingston-flemings-rises-up-for-the-dunk' --license 'unknown (Getty Images / NBAE via NBA.com)' --author 'Getty Images / NBAE' --date '2026-10-08 (2026-27 preseason at SAS, Frost Bank Center; Getty caption: handles the ball)' --crop 220,0,920 --scores 3,3,3,2,2,2,1 --energy 6 --vs-mccain 'slightly lower (alert, eyes off-camera to his right, lips parted with the lower lip caught in his teeth mid-dribble; more composed than McCain)' --jersey 'ATL red icon, 2026-27 preseason' --concerns '2026 draftee (Houston), no NBA regular season yet: 2026-27 preseason game; nba.com 1920x1080 crop of the Getty original, so the top of his braids sits at the image edge (hair top ~2% down the crop, less headroom than wanted); the only other nba.com Flemings photo is the posed July 2026 rookie photo shoot' --alt 'https://cdn.nba.com/manage/2026/09/GettyImages-2286263008.jpg (nba.com, 2026 Rookie Photo Shoot portrait, posed, off-rule)'
node scripts/portraits/select-source.js --slug jamal-cain --url 'https://cdn.nba.com/teams/uploads/sites/1610612753/2026/06/cain-release-20260629.jpg' --page 'https://www.nba.com/magic/news/orlando-magic-jamal-cain-exercise-team-option-20260629' --license 'unknown (Orlando Magic via NBA.com)' --author 'Orlando Magic' --date '2025-26 season (undated team photo on the June 29 2026 team-option release)' --crop 1121,59,789 --scores 3,3,3,2,2,2,1 --energy 6.5 --vs-mccain 'slightly lower (eyes off-camera to his right, lips parted mid-breath, alert during a stoppage; head level rather than tipped up)' --jersey 'ORL blue pinstripe icon #8, 2025-26' --concerns 'played 2025-26 with ORL (low minutes, so missing from our season data) and is on the 2026-27 roster; renamed team-site photo, no caption, exact game unverified; slightly warm colour grade; 2025-26 rather than 2026-27 (same team): the only 2026 preseason photo on nba.com is a dunk' --alt 'https://cdn.nba.com/manage/2026/10/GettyImages-2298506153_cropped.jpg (nba.com, 2026-10-07 preseason at MEM, mid-dunk, face at the rim, off-band)' --alt 'https://cdn.nba.com/manage/2026/04/GettyImages-2272966621-scaled-e1777353578388.jpg (nba.com, 2026 playoffs G4 vs DET, dunk, off-band)'
node scripts/portraits/select-source.js --slug lamarcus-aldridge --url 'https://cdn.nba.com/manage/2017/10/20171021_lamarcus_aldridge_black-scaled.jpg' --page 'https://www.nba.com/watch/video/report-aldridge-spurs-agree-to-part-ways' --license 'unknown (NBA.com)' --author 'NBA.com' --date '2017-10-21 per filename (2017-18, road game; undated renamed nba.com photo)' --crop 688,0,960 --scores 3,3,3,2,2,2,1 --energy 7 --vs-mccain 'matches (eyes up and off-camera, mouth open mid-breath, engaged at a stoppage)' --jersey 'SAS black road #12, 2017-18' --concerns 'renamed nba.com image, no Getty caption check, so the exact game is unverified (filename date 2017-10-21, red-seated road arena); 2017-18 rather than his 2015-16 best season (same team, his Spurs prime); little headroom above the hair (~5%)' --alt 'https://cdn.nba.com/manage/2021/03/lamarcus-aldridge-looks-iso.jpg (nba.com, SAS black 2020-21, looking up with mouth open, energy ~6.5, head turned 3/4 and hair at the top edge, smaller face)' --alt 'https://cdn.nba.com/manage/2018/10/aldridge-davis-iso-1017.jpg (nba.com, SAS white, frontal crouched stare beside Anthony Davis, Davis’s arm at the edge, smaller face)' --alt 'https://upload.wikimedia.org/wikipedia/commons/8/89/LaMarcus_Aldridge_2017.jpg (Commons, 2017 vs ORL, SAS black, full body, small face)'
node scripts/portraits/select-source.js --slug derek-fisher --url 'https://upload.wikimedia.org/wikipedia/commons/9/95/Derek_Fisher_2008.jpg' --page 'https://commons.wikimedia.org/wiki/File:Derek_Fisher_2008.jpg' --license 'CC BY 2.0' --author 'Stephanie Young Merzel' --date '2008-05-11 (2008 West semifinals Game 4 at UTA, EnergySolutions Arena)' --crop 50,178,1100 --scores 2,3,3,2,2,2,1 --energy 6 --vs-mccain 'slightly lower (eyes up and off-camera to his right, lips parted mid-breath, set for a free throw; calmer than McCain)' --jersey 'LAL purple road #2, 2007-08' --concerns 'Commons (CC BY 2.0), not nba.com: the nba.com content API refused requests this session, so no nba.com search; 2007-08 (second Lakers stint, title-era look) rather than his 2001-02 best season; slightly soft and grainy 1683x2000 image; blurred PLAYOFFS banner behind him' --alt 'https://upload.wikimedia.org/wikipedia/commons/b/b7/Derek_Fisher_high_fives_Kobe_Bryant.jpg (Commons, 2012 at WAS, LAL purple, back to camera high-fiving Kobe, face hidden)' --alt 'https://upload.wikimedia.org/wikipedia/commons/4/47/Derek_Fisher_Paul_Gasol.jpg (Commons, 2008, LAL purple, full body, small face)'
node scripts/portraits/select-source.js --slug clifford-robinson --url 'https://cdn.arizonasports.com/arizonasports/wp-content/uploads/2020/08/GettyImages-72316749.jpg' --page 'https://arizonasports.com/?p=2371742' --license 'unknown (Getty Images / Allsport, via Arizona Sports 98.7)' --author 'Ronald Martinez / Allsport' --date 'April 2000 (2000 West first round at SAS, Alamodome; Getty caption: walks on the court, Spurs won 85-70, i.e. Game 2)' --crop 440,144,1150 --scores 2,3,3,2,2,2,1 --energy 6.5 --vs-mccain 'matches in intensity, different mood (open-mouthed grin mid-reaction while walking upcourt, eyes off-camera to his right)' --jersey 'PHX black road #30, 1999-2000' --concerns 'not nba.com or Commons: Getty/Allsport original (no watermark) served by an Arizona Sports obituary page, license unknown; Commons has no photo of him and nba.com was unreachable this session; 1999-2000 rather than his 1998-99 best season (same team and look); smiling rather than concentrating; film grain' --alt 'https://images.foxtv.com/static.fox10phoenix.com/www.fox10phoenix.com/content/uploads/2020/08/GettyImages-1185785601.jpg (AFP via Fox 10, 2000 playoffs vs SAS, PHX white, shouting after a basket, energy ~9, off-band)'
